[JsonConstructor]
        public CloudEventExtension(          
            string specversion,
            string type,
            Uri source,
            string id,
            DateTime time,
            string subject,
            string datacontenttype,
            Data? data)
        {
            this.cloudEvent = new CloudEvent(CloudEventsSpecVersion.V1_0)
            {
                Data = data,
                DataContentType = datacontenttype,
                Id = id,
                Subject = subject,
                Time = time,
                Type = type,
                Source = source
            };
            this.specVersion = specVersion;
            this.type = type;
            this.source = source;
            this.id = id;
            this.time = time;
            this.subject = subject;
            this.dataContentType = dataContentType;
            this.data = data;
        }

